"""Parser for the supplier's stock feed (CSV, one row per SKU)."""
import csv
import io


def parse_feed(text):
    rows = csv.DictReader(io.StringIO(text))
    return {row["sku"].strip(): int(row["qty"]) for row in rows}

from src.feed import parse_feed
from src.settings import load_settings
from src.sync import sync_stock

SAMPLE_FEED = """sku,available,updated_at
NG-1001,4,2026-09-27T06:00:00Z
NG-1002,12,2026-09-27T06:00:00Z
NG-1003,80,2026-09-27T06:00:00Z
"""

REORDER_POINTS = {"NG-1001": 10, "NG-1002": 10, "NG-1003": 25}


def test_parse_feed():
    assert parse_feed(SAMPLE_FEED) == {"NG-1001": 4, "NG-1002": 12, "NG-1003": 80}


def test_parse_feed_strips_sku():
    text = "sku,available,updated_at\n NG-1004 ,7,2026-09-27T06:00:00Z\n"
    assert parse_feed(text) == {"NG-1004": 7}


def test_settings_defaults():
    assert load_settings()["safety_stock"] == 5


def test_sync_stock_levels():
    stock, _ = sync_stock(SAMPLE_FEED, REORDER_POINTS)
    assert stock["NG-1003"] == 80


def test_sync_reorders_below_point_plus_safety_stock():
    _, to_reorder = sync_stock(SAMPLE_FEED, REORDER_POINTS)
    assert to_reorder == ["NG-1001", "NG-1002"]

